def test_sha_bound_fixer_receipts_chain_heads_before_fresh_review_and_merge(tmp_path):
    from deploy.task_receipts import validate_task_receipt

    result_head = "c" * 40
    api = FakeApi(unresolved=True)
    api.comments[0]["body"] = f"/hermes enroll {HEAD}"
    api.review_sha = HEAD
    store = StateStore(tmp_path / "state.json")
    coordinator = lambda: Coordinator(
        api, StateStore(store.path), clock=lambda: 1790856540,
    )

    first_result = coordinator().run(apply=True)
    fixes = [
        action for action in store.actions().values()
        if action.get("kind") == "fix"
    ]
    assert fixes, json.dumps(
        {"result": first_result, "state": store.snapshot()},
        sort_keys=True,
    )
    first_fix = fixes[0]
    anchor_comments = [
        comment for comment in api.comments
        if comment.get("body", "").startswith(
            "hermes-coordinator-source-receipt:",
        )
    ]
    assert len(anchor_comments) == 1
    assert first_fix["receipt_anchor_comment_id"] == anchor_comments[0]["id"]
    assert first_fix["receipt_anchor_body"] == anchor_comments[0]["body"]
    assert first_fix["receipt_anchor_role"] == "continuation-source"
    anchor_post = next(
        index for index, (route, body) in enumerate(api.writes)
        if route == "repos/lindayi/hermes-mobile/issues/16/comments"
        and body.get("body") == anchor_comments[0]["body"]
    )
    task_post = next(
        index for index, (route, body) in enumerate(api.writes)
        if route == "agents/repos/lindayi/hermes-mobile/tasks"
        and body.get("prompt") == first_fix["body"]
    )
    assert anchor_post < task_post

    def finish_task(action, current_head, comment_id, *, transported=False):
        task = api.tasks[action["task_id"]]
        created = "2026-10-01T12:06:00Z"
        task.update(
            state="completed",
            updated_at=created,
            sessions=[{
                "id": f"session-{action['task_id']}",
                "task_id": action["task_id"],
                "state": "completed",
                "user": {"id": OWNER},
                "owner": {"id": OWNER},
                "repository": {"id": 1399942965},
                "head_ref": "topic",
                "base_ref": "main",
                "prompt": action["body"],
                "created_at": "2026-10-01T12:01:00Z",
                "completed_at": created,
            }],
        )
        if transported:
            api.neutral_quote_envelope = ("\n", "", ">\n", "\t")
        if action.get("receipt_anchor_comment_id") is not None:
            body = (
                "Hermes-Task-Receipt: v2\n"
                f"nonce={action['dispatch_nonce']}\n"
                "pr=16\n"
                f"session=session-{action['task_id']}\n"
                f"start_head={action['head']}\n"
                f"base={BASE}\n"
                f"head={current_head}\n"
                "result=ready"
            )
            api.reply_to_comment(action["receipt_anchor_comment_id"], body)
            api.neutral_quote_envelope = ("\n", "", "", "")
            return
        elif transported:
            body = (
                "\n> Cloud completion report preserved before parent normalization:\n"
                "> \n"
                "> This quoted report is not receipt evidence.\n\n"
                "Hermes-Task-Receipt: v2\n"
                f"nonce={action['dispatch_nonce']}\n"
                "pr=16\n"
                f"session=session-{action['task_id']}\n"
                f"start_head={action['head']}\n"
                f"base={BASE}\n"
                f"head={current_head}\n"
                "result=ready"
            )
        else:
            body = (
                "Hermes-Task-Receipt: v1\n"
                f"nonce={action['dispatch_nonce']}\n"
                f"task={action['task_id']}\n"
                f"session=session-{action['task_id']}\n"
                "pr=16\n"
                f"start_head={action['head']}\n"
                f"head={current_head}\n"
                f"base={BASE}\n"
                "result=ready"
            )
        api.comments.append({
            "id": comment_id, "user": {"id": 198982749}, "body": body,
            "created_at": created, "updated_at": created,
        })

    api.head_sha = result_head
    api.pull["head"]["sha"] = result_head
    finish_task(first_fix, result_head, 900, transported=True)
    api.unresolved = False
    refresh_owner_review(api, result_head)
    api.review_sha = result_head
    api.source_failure = True
    api.source_failure_sha = result_head
    validate_task_receipt(
        api.tasks[first_fix["task_id"]], first_fix, api.pull, api.comments,
        now=datetime.fromtimestamp(1790856540, timezone.utc),
    )
    coordinator().run(apply=True)

    first_proof = store.action(first_fix["key"]) or next(
        proof for proof in store.snapshot()["enrollments"]["16"]["receipt_proofs"]
        if proof["task_id"] == first_fix["task_id"]
    )
    assert first_proof["receipt_result"] == "ready"
    assert first_proof["receipt_start_head"] == HEAD
    assert first_proof["receipt_head"] == result_head
    assert api.fix_attempts == 2
    assert api.review_attempts == 0
    assert not any(route.endswith("/requested_reviewers") for route, _ in api.writes)
    durable = store.snapshot()["enrollments"]["16"]["receipt_proofs"][0]
    assert durable["receipt_start_head"] == HEAD
    assert durable["receipt_head"] == result_head
    second_fix = next(
        action for action in store.actions().values()
        if (action.get("kind") == "fix"
            and action.get("task_id") != first_fix["task_id"]
            and action.get("head") == result_head)
    )
    assert second_fix["head"] == result_head

    finish_task(second_fix, result_head, 901)
    api.unresolved = False
    api.source_failure = False
    result = coordinator().run(apply=True)
    assert store.action(second_fix["key"])["receipt_head"] == result_head
    assert api.graphql_writes[-1][1]["expectedHeadOid"] == result_head
    assert result["pull_requests"][0]["auto_merge_requested"] is True
    assert store.snapshot()["enrollments"]["16"]["authorized_head"] == HEAD
    coordinator().run(apply=True)
    assert len(api.graphql_writes) == 1
    assert api.fix_attempts == 2


@pytest.mark.parametrize("inventory_change", [False, True, "deleted"])
def test_pending_enrollment_uses_later_inventory_before_apply(
        tmp_path, inventory_change):
    api = FakeApi(unresolved=True)
    api.comments[0]["body"] = f"/hermes enroll {HEAD}"
    store = StateStore(tmp_path / "state.json")
    store.preserve_pending_events(["123"])
    original_get = api.get
    original_get_all = api.get_all
    exact_reads = []
    inventory_reads = []

    def get(route):
        value = original_get(route)
        if route == "repos/lindayi/hermes-mobile/issues/comments/123":
            exact_reads.append(deepcopy(value))
        return value

    def get_all(route, *, collection=None):
        if route.startswith("repos/lindayi/hermes-mobile/issues/16/comments?"):
            assert exact_reads
            if inventory_change is True:
                api.comments[0]["body"] = f"/hermes enroll {'c' * 40}"
                api.comments[0]["updated_at"] = "2026-10-01T11:01:00Z"
            elif inventory_change == "deleted":
                api.comments[:] = [
                    comment for comment in api.comments if comment["id"] != 123
                ]
            comments = original_get_all(route, collection=collection)
            inventory_reads.append(deepcopy(comments))
            return comments
        return original_get_all(route, collection=collection)

    api.get = get
    api.get_all = get_all
    Coordinator(api, store, clock=lambda: 1790856900).run(apply=True)

    assert exact_reads[0]["body"] == f"/hermes enroll {HEAD}"
    assert exact_reads[0]["created_at"] == exact_reads[0]["updated_at"]
    assert inventory_reads
    state = StateStore(store.path).snapshot()
    if inventory_change is True:
        assert inventory_reads[0][0]["updated_at"] != inventory_reads[0][0]["created_at"]
        assert state["enrollments"] == {}
        assert state["actions"] == {}
        assert api.task_posts == 0
        assert api.writes == []
    elif inventory_change == "deleted":
        assert inventory_reads and all(not comments for comments in inventory_reads)
        assert state["enrollments"] == {}
        assert state["actions"] == {}
        assert state["pending_events"] == ["123"]
        assert api.task_posts == 0
        assert api.writes == []
    else:
        assert state["enrollments"]["16"]["authorized_head"] == HEAD
        assert api.task_posts == 1


@pytest.mark.parametrize("identity", ["string", "float", "duplicate"])
def test_pending_hint_does_not_hide_invalid_inventory_identity(tmp_path, identity):
    api = FakeApi(unresolved=True)
    api.comments[0]["body"] = f"/hermes enroll {HEAD}"
    store = StateStore(tmp_path / "state.json")
    store.preserve_pending_events(["123"])
    original_get_all = api.get_all

    def get_all(route, *, collection=None):
        values = original_get_all(route, collection=collection)
        if route.startswith("repos/lindayi/hermes-mobile/issues/16/comments?"):
            row = deepcopy(values[0])
            if identity == "duplicate":
                return [row, deepcopy(row)]
            row["id"] = "123" if identity == "string" else 123.0
            return [row]
        return values

    api.get_all = get_all
    with pytest.raises(CoordinatorError, match="comment identity was malformed"):
        Coordinator(api, store, clock=lambda: 1790856900).run(apply=True)
    assert StateStore(store.path).snapshot()["enrollments"] == {}
    assert api.task_posts == 0
    assert api.writes == []


@pytest.mark.parametrize("negative", ["missing", "closed", "non-pr", "transient"])
def test_pending_issue_negative_lookup_is_cached_only_per_scan(tmp_path, negative):
    api = FakeApi()
    api.comments.append(api.comments[0] | {"id": 124})
    coordinator = Coordinator(api, StateStore(tmp_path / "state.json"))
    original_get = api.get
    issue_reads = []

    def get(route):
        if route == "repos/lindayi/hermes-mobile/issues/16":
            issue_reads.append(route)
            if negative == "missing":
                raise ApiError("Synthetic missing issue", status=404)
            if negative == "transient":
                raise ApiError("Synthetic issue outage", status=503)
            value = original_get(route)
            if negative == "closed":
                return value | {"state": "closed"}
            if negative == "non-pr":
                return value | {"pull_request": None}
        return original_get(route)

    api.get = get
    state = {"pending_events": ["123", "124"]}
    if negative == "transient":
        with pytest.raises(ApiError, match="Synthetic issue outage"):
            coordinator._pending_event_issues(state, [])
    else:
        assert coordinator._pending_event_issues(state, []) == ([], {})
    assert len(issue_reads) == 1

    negative = None
    issues, comments = coordinator._pending_event_issues(state, [])
    assert len(issue_reads) == 2
    assert issues == [api.issue]
    assert set(comments[16]) == {"123", "124"}


