    anchor_id = successors[0]["receipt_anchor_comment_id"]
    for _ in range(2):
        Coordinator(
            api, StateStore(store.path), clock=lambda: 1790856901,
        ).run(apply=True)
    assert api.task_posts == posts + 1
    assert len([item for item in api.comments if item.get("id") == anchor_id]) == 1


