    assert new_writes[0][0] == "agents/repos/lindayi/hermes-mobile/tasks"
    assert "PR #17" in new_writes[0][1]["prompt"]
    assert api.graphql_writes[before_graphql_writes:] == []

    retry_writes = len(api.writes)
    retry_posts = api.task_posts
